WITH exploded AS (SELECT id, service, log_ts, level, latency_ms, status_code, key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS key, v) SELECT *, CUME_DIST() OVER (PARTITION BY service ORDER BY status_code DESC) status_code_cume_dist, MAX(latency_ms) OVER (PARTITION BY level ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) latency_ms_max_30m, RANK() OVER (PARTITION BY key ORDER BY latency_ms DESC) latency_ms_rank, ROUND(status_code / SUM(status_code) OVER (PARTITION BY key), 4) status_code_share, CUME_DIST() OVER (ORDER BY status_code DESC) status_code_cume_dist_2 FROM exploded;
